<?php

namespace Tests\Filament;

use Filament\Facades\Filament;
use PHPUnit\Framework\Attributes\Group;
use Tests\TestCase;

/**
 * DEV-2089: a 419 (expired CSRF token — e.g. the session regenerated by the
 * impersonation handoff) must fall through to Livewire's native page-expired
 * reload instead of Filament's dead "Error while loading page" toast. Disabling
 * the 419 error notification is what lets that recovery run.
 */
class PanelErrorRecoveryTest extends TestCase
{
    #[Group('panels')]
    public function test_app_panel_lets_livewire_recover_from_expired_csrf_token(): void
    {
        $notifications = Filament::getPanel('app')->getErrorNotifications();

        $this->assertTrue($notifications[419]['isDisabled'] ?? false);
    }

    #[Group('panels')]
    public function test_client_panel_lets_livewire_recover_from_expired_csrf_token(): void
    {
        $notifications = Filament::getPanel('client')->getErrorNotifications();

        $this->assertTrue($notifications[419]['isDisabled'] ?? false);
    }
}
